def compute(vars):
    priceline = vars["v1"]
    nasdaq_composite = vars["v2"]

    if nasdaq_composite == 0:
        value = None
    else:
        value = priceline / nasdaq_composite

    return {
        "value": value,
        "trace": {
            "priceline_measurement_point": priceline,
            "nasdaq_composite_measurement_point": nasdaq_composite,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "ratio"
            }
        }
    }
